-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx462327a064bf$doc_5_18_2021_the_prevention_of_corruption_act_2059_2002_a_d_nepal_law_commission_2059_prevention_of_corruption_ac$CODEx462327a064bf$,$CODEx207e869be98b$5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission$CODEx207e869be98b$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2059,2002,25,$CODExfdad488d5fbd$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 1/25\nThe Prevention of Corruption Act, 2059 (2002 A.D)\nThe Prevention of Corruption Act, 2059 (2002 A.D) \nDate of Authentication and publication \n3 Asadha, 2059 (June 17, 2002) \nAct number 1 of the year 2059 (2002) \nPreamble: Whereas, it is expedient to make timely legal provisions relating \nto prevention of corruption with a view to maintaining peace, convenience, \nfinancial discipline, morality and good conduct among general public; \nBe it enacted by Parliament in the first year of the reign of His Majest y ‘s the King \nGyanendra Bir Bikram Shah Dev\nChapter – 1 Preliminary\nChapter – 1 Preliminary", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title, Extent and Commencement:", "content": "(1) This Act may be called the “Prevention of Corruption Act, 2059 (2002 A.D.).”\n(2) It shall be extended throughout Nepal and applicable to all Nepalese citizens, public\nservants residing anywhere outside Nepal and to the non- Nepalese citizens residing in\nforeign countries having committed \nany act that may be deemed to be corruption under this Act. \n(3) It shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: In this Act, unless the context otherwise requires-", "content": "(a) “Corruption” means o\u0000ences punishable under Chapter -2. \n(b) “Gra\u0000” means cash, goods or any type of gain or benefit and the term also includes bribe. \nNovember 15, 2018 in The Prevention of Corruption Act, 2059 (2002 A.D)\n MENU\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 2/25\n(c) “Public institution” means the following institutions:- \n(1) A company, bank or a committee fully or partially owned or controlled by Government of\nNepal; or a \ncommission, organization, authority, corporation, academy, board, center, council or any\nother corporate body of such nature established by Government of Nepal; \n(2) A university, college, school, research center and any other similar academic or\neducational institution run by \nGovernment of Nepal or on the full or partial donation from Government of Nepal; \n(3) Local bodies constituted under the Local Self-Governance Act, 1999; \n(4) An institution run on loan, grant or guarantee of Government of Nepal; \n(5) An institution fully or partially owned or controlled by the institution referred to in Sub-\nclauses (1), (2), (3) or (4) or obtained grant from such institution; and (6) Any other institution\nprescribed as public institution by \nGovernment of Nepal in a notification published by the Nepal Gazette. \n(d) “Public Servant” means the person holding a public o\u0000ice under the prevailing laws and\nthe term also includes the following persons:- \n(1) person appointed, nominated or elected under an oath to Government of Nepal or to\npublic institution, or under the terms, contracts or agreements concluded with Government\nof Nepal or with any public institution, or holding any o\u0000ice of public responsibility for salary\nor allowances or remuneration or benefit or position with or without any type of gain from\nGovernment of Nepal or any public institution; \n(2) A person appointed as an arbitrator or any other person appointed in the same position\npursuant to the prevailing laws to resolve or adjudicate any dispute; \n(3) A person appointed, elected or nominated as liquidator, surveyor or any other person\nworking in the same capacity in accordance with the prevailing laws; \n(4) A person designated as public servant by Government of Nepal in a notification published\nin the Nepal Gazette. \n(e) “Revenue” means any type of tax, fee, charge, royalty, fine and other amount of this type\nto be paid or given to Government of Nepal or public institution, and the term also includes\ninterest or fine to be charged on such tax, fees, royalty and other amount of this type. \n(f) “Degree of o\u0000ence” means the degree of o\u0000ence to be determined on the basis of\ncircumstances and situation in which the o\u0000ence has been committed or attempted to be\ncommitted, the gravity of such o\u0000ence or the intention, qualification, position and capacity\nof the person who has committed or attempted to commit any o\u0000ence \npunishable under this Act. \n(g) “Investigating Authority” means the body or o\u0000icial authorized to conduct inquiry,\ninvestigation and to file cases relating to corruption in accordance with the prevailing laws.\nNovember 15, 2018 in The Prevention of Corruption Act, 2059 (2002 A.D)\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 3/25\nChapter – 2 Provisions Relating to O\u0000ences of Corruption\nand Punishment\nChapter – 2 Provisions Relating to O\u0000ences of Corruption and Punishment", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Punishment to Giver and Taker of Gra\u0000:", "content": "(1) Whoever, being, or expecting to become, a public servant accepts or agrees to accept\ngra\u0000 amounting as follows for him/herself or for any other person in consideration of his/her\nperforming or having performed or of \nforbearing to perform or having forborne to perform any act pertaining to his/her o\u0000ice or the\nrelated act or in consideration of favouring or disfavouring or causing or not causing a loss or\nof having favoured or disfavoured or having caused or not caused a loss to any person\nwhile carrying out his/her o\u0000icial functions, shall be liable to a punishment of imprisonment\nas follows and of a fine as per the amount involved depending on the degree of the o\u0000ence.\nIn case the gra\u0000 has already been accepted, it shall be confiscated. \n(a) Up to twenty five thousand rupees. Imprisonment for a term not exceeding three months. \n(b) More than twenty five thousand Imprisonment for a term from rupees to fi\u0000y thousand\nrupees. three to four months. \n(c) More than fi\u0000y thousand rupees to Imprisonment for a term from four one hundred\nthousand rupees. to six months. \n(d) More than one hundred thousand Imprisonment for a term from six rupees to five\nhundred thousand months to one year and six months. rupees. \n(e) More than five hundred thousand Imprisonment for a term from one rupees to one million\nrupees. year and six months to two years and six months. \n(f) More than one million rupees to two Imprisonment for a term from two million and five\nhundred thousand years and six months. rupees. \n(g) More than two million and five Imprisonment for a term from four hundred thousand\nrupees to five to six years. \nmillion rupees. \n(h) More than five million rupees to ten Imprisonment for a term from six million rupees. to\neight years. \n(i) Whatsoever amount above ten Imprisonment for a term from million rupees. eight to ten\nyears. \n(2) Whoever, other than a public servant, accepts or agrees to accept gra\u0000 amounting as\nfollows for him/herself or for any other person with the intention of convincing any public\nservant to perform or forbear to perform any function under his/her o\u0000ice or position or for\nconvincing to perform or forbear to perform any such act or with the intention of favoring or\ndisfavoring any person or causing or not causing any loss or for convincing to perform or\nforbear to perform any such act while carrying out any function under his o\u0000ice or position,\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 4/25\nshall be liable to a \npunishment of imprisonment as follows and of a fine as per the amount involved depending\non the degree of the o\u0000ence. In case the gra\u0000 has already been accepted, it shall be\nconfiscated. \n(3) Whoever gives a gra\u0000 to a public servant or any other person in order to do or forbear to\ndo any function pursuant to Sub-Section (1) or (2), shall be liable to a punishment pursuant\nto Sub-Section (1) depending on the \ndegree of the o\u0000ense committed. \n(4) Whoever abates to commit an o\u0000ence punishable under this Section shall, if he/she is a\npublic servant, be liable to a punishment as same as the punishment prescribed for the same\no\u0000ence, and if he/she is any other person, shall \nbe liable to half of the punishment for that o\u0000ence on the basis of the degree of the o\u0000ence\nirrespective of whether or not the o\u0000ence has been committed because of such abetment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Punishment to Public Servants Accepting Goods or Service Free of Cost or at Lower Prices:", "content": "Whoever, being a public servant, accepts or agrees or attempts to accept, without a prior\napproval of Government of Nepal or public \ninstitution, any goods or service free of cost or at lower prices for him/herself or for any other\nperson, from any individual, having knowledge that such individual is related to or is likely to\nbe related to any act related to his/her o\u0000ice or any act carried out or to be carried out by\nhim/herself is related to any function of his o\u0000ice, shall be liable to a punishment of\nimprisonment for a term from six months to one year depending on the degree of the o\u0000ence\nand a fine equal to the amount involved and in case such goods is already accepted, it shall\nbe confiscated and in case of the service, the price thereof shall be fixed and a fine equal to\ntheprice of such service shall be imposed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Punishment for Taking Gi\u0000, Present, Award or Donation: (1) Whoever, being a public", "content": "servant, accepts, without a prior approval Government of Nepal or a public institution, any\ntype of donation, gi\u0000s, presents, awards or any \ntype of benefit him/herself or through any member of his/her family or other person, so as to\ncausing an impact in any way on any of his/her works which is supposed to be carried out by\nhim/her according to the o\u0000ice he/she assumes; or any public servant who borrows from a\nperson related to a work which he/she \nhas to carry out according to the o\u0000ice he assumes, shall be liable to a punishment of\nimprisonment from three to six months depending on the degree of the o\u0000ence and the\namount shall be confiscated. \n(2) Whoever, being a public servant, has received any present or gi\u0000 in exchange of a gi\u0000 or\npresent brought from the amount of a fund belonging to Government of Nepal or a public\ninstitution, such gi\u0000 or present \nshall be immediately submitted to his/her o\u0000ice. If not submitted, it shall be deemed to have\ncommitted the o\u0000ence referred to in Sub-section (1) and such gi\u0000 or present shall be\nconfiscated having him/her punished accordingly. \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 5/25", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Punishment for Taking Commission: In case any type of commission,", "content": "remuneration, brokerage fee, benefit or advantage is liable to be paid while \nperforming duties by a public servant or while purchasing or hiring or taking or \ngiving on a lease any commodity or service necessary for Government of \nNepal or a public institution or while awarding or accepting a contract by \nGovernment of Nepal or a public institution or while selling or hiring or \ntaking or giving on a lease any commodity or service produced by Government \nof Nepal or a public institution, such commission, remuneration, brokerage fee, \nbenefit or advantage shall be submitted to the concerned o\u0000ice within seven \ndays from the date of receipt. In case not submitted as such, such public servant \nshall be deemed to have committed the o\u0000ence referred to in Section 3 and the \namount shall be confiscated having him/her punished accordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Punishment to Public Servants for Leaking Revenue: Whoever, being a", "content": "public servant under the duty of collecting revenues, causes revenue leakage or \nhelp or abets any person for its leakage having been involved him/herself in \nany of the following manners, shall be deemed to have committed the o\u0000ence \nreferred to in Section 3 with regard to the amount of revenue so leaked and \nhe/she shall be liable to the same punishment of imprisonment, and double of \nthe amount of revenue leaked shall be fined: – \n(a) To assist any person in the act of leaking revenue in any manner \nwhatsoever, having accepted any cash or kind, fee, prize or donation \nor any type of other benefit or forbear to collect revenue or to assist or \ncause to assist to collect less revenue having caused loss to Government \nof Nepal or a public institution by taking or not taking any type of gain \nfrom any person; \n(b) To assess or assist to assess less revenue or to assess revenue to \nthe e\u0000ect of not charging revenue at all by not going through the \ndocuments or not investigating such documents or by not collecting \nnecessary evidence while assessing revenue as required by the \nexisting law; \n(c) To embezzle the revenue collected by not depositing it in \naccordance with the prevailing laws; \n(d) To release or assist to release goods, by making di\u0000erence in the \ninvoice, quality or quantity of such goods, and without collecting \nthe prescribed revenue while assessing the revenue or carrying out \nvaluation of such goods.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Punishment to Public Servants for Getting Illegal Benefit or Causing", "content": "Illegal Loss with Mala fide Intention: (1) Whoever, being a public servant, \ncommits any of the following acts with the mala fide intention of getting \nillegal benefits for him/herself or for any other person, or of causing loss to \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 6/25\nGovernment of Nepal or public institution, shall be liable to an \nimprisonment of a term from three months to three years depending on \nthe degree of o\u0000ence, and in case the amount involving the o\u0000ence is \nknown, such amount shall be confiscated having him/her fined \naccordingly. In case such amount is not known, an imprisonment for \na term from three months to three years and a fine from ten thousand to \nfi\u0000y thousand rupees shall be imposed. \n(a) To show more costs or works in an unnatural manner \nwithout any ground of justification while conducting physibility \nstudy of, or setting norms for, a project. \n(b) To use or allow to use the construction materials of lower \nquality than that of the prescribed quality, or to certify or \nto approve the use of such materials as the materials of \nprescribed quality; \n(c) To degrade the quality of construction work or to change the \nform or shape thereof or to carry out or cause to carry out \nconstruction works in contravention of the prescribed \nterms, conditions and standard; or to certify or to \napprove such construction work as qualitative and under \nthe prescribed terms and conditions without any reasonable \nground; \n(d) To carry out or cause to carry out construction works having \nincreased or amended the costs estimate in an unnatural manner \nand without any reasonable ground; \n(e) To give or receive payment having prepared false bills or \nreceipts or to give or receive double payment of bills; \n(f) To procure or cause to procure excessive quantity of goods in \nan unnatural manner than the quantity needed without reasonable \ngrounds; \n(g) To carry out or cause to carry out unnatural valuation of a \ngovernment property, a property of a public organization or of \npublic property; \n(h) To register, occupy or use or to cause to register, occupy or use \na government or public property in one’s own name or in the \nname of other in an illegal manner; \n(i) To value or cause to value a collateral security to be \nmortgaged in the name of a governmental or public \norganization in an excessive and unreasonable prices than the \nreal prices; \n(j) To procure or cause to procure goods of degrading quality, \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 7/25\ndate expired and to procure or cause to procure goods \nhaving paid higher prices in an unnatural manner. \n(2) In case any public servant does not return a vehicle or a facility \navailable to him/her by virtue of his/her o\u0000icial position within the \nprescribed time a\u0000er the expiry of the o\u0000icial position without any \nreasonable ground, he/she shall be liable to a fine from one thousand to \nfive thousand rupees depending on the degree of the o\u0000ense and such \nvehicle or facility shall be taken back. \n(3) Whoever, being a public servant, causes any type of loss to a \ngovernmental or public property with mala fide intention having \ncommitted any act excluding the acts referred to in Sub-Section (1) and (2), \nshall be liable to a punishment of imprisonment not exceeding two years or of \na fine equal to the amount of the loss or both depending on the degree of \nthe o\u0000ence. \n(4) In case any person other than a public servant, with mala \nfide intention of making illegal gain to him/herself or to any other \nperson, does not abide by the terms and conditions of an oath, \nundertaking, agreement, contract, license, permit, promissory note or \ndealership entered into with Government of Nepal or a public institution or \ncarries out business or misuses the facilities or powers of governmental or \nsuch institution violating the Rules or Procedures determined by or terms \nand conditions accepted by Government of Nepal or such institution in a \nmanner prohibited by the prevailing law, he/she shall be liable to a \npunishment of imprisonment not exceeding two years and be fined \naccording to the amount of loss and the amount of loss shall be confiscated.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Punishment to Public Servants Preparing False Documents: Whoever,", "content": "being a public servant under the duty of preparing documents, prepares \nfalse documents with mala fide intention of causing loss to Government of \nNepal or Government or public institution, shall be liable to a punishment \nof imprisonment for a term from three months to one year, and a fine from ten \nthousand to fi\u0000y thousand rupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Punishment for Translating False Documents: Whoever, either a public", "content": "servant or any other person authorized or designated to translate \ndocuments, wrongly translates documents, translates documents \nincorporating therein false particulars or makes di\u0000erence in the name, \nsurname, date, facts or other particulars with the mala fide intention of \ncausing loss to Government of Nepal, a Government or public institution; \nor with the intention of getting illegal benefit to him/herself or to any other \nperson, shall be liable to a punishment of imprisonment for a term from \nthree months to one year and of a fine from ten thousand to fi\u0000y thousand \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 8/25\nrupees, depending on the degree of o\u0000ence committed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Punishment for Tempering Government Documents: Whoever, either a", "content": "public servant or any other person, corrects, adds, or changes in \ndocuments belonging to a government or public institution without \nauthority or in an illegal manner, shall be liable to a punishment of \nimprisonment for a term from three months to two years and a fine not \nexceeding fi\u0000y thousands rupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Punishment for Causing Damage to Government or Public Documents:", "content": "Whoever, being a public servant, conceals a document belonging to \ngovernment or to a public institution or causes damage to, or destroys, \nsuch document, shall be liable to a punishment of imprisonment \nfrom six month to one year and shall be fined from ten thousand to \nfi\u0000y thousand rupees. In case any loss is incurred due to such \nconcealment, damage or destruction, the loss shall also be recovered.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Punishment for Disclosing Secrecy of Question Papers or Altering the", "content": "Result of Examination: Save in cases where the authorized person \ndiscloses or causes to disclose question papers of an examination to be \nconducted by a government body or a public institution before the \nprescribed time having given reasons of special circumstances, \nwhoever, being a public servant, discloses or causes to disclose the secrecy \nof such question paper in any manner whatsoever, or alters or causes to \nalter the results of examinations with the intention of making illegal \nadvantage to him/herself or any other person, shall be liable to a \npunishment of imprisonment from three months to one year and shall be \nfined from five thousand to ten thousand rupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Punishment to Public Servants Engaging in Illegal Trade or Business:", "content": "Whoever, being a public servant, engages in trade or business in his/her \nown name or in the name of other person or in partnership with others, \ntakes part in auction or bidding, or becomes a partner in any firm or \ncompany or a cooperative organization while being prohibited by law, shall \nbe liable a punishment of imprisonment for a term from three months to \nsix months and a fine from ten thousand to fi\u0000y thousand rupees, and the \nproperty earned in such a manner shall be confiscated. \nProvided that, this section shall not be deemed to have hindered to \nsubscribe shares of a public limited company called for public subscription.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Punishment for Claiming False Designation: Whoever, either a public", "content": "servant or any other person falsely claims that he/she holds any position, \npower, capacity or facility or enjoys such position, power, capacity or facility \nof a public servant which he/she is not entitled to or displays any symbol, dress \nor mark relating to a position of a public servant or wears or displays any \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 9/25\nobject resembling to such symbol, dress or mark with the intention of \nleading others to falsely believe that these are the o\u0000icial symbols, dresses \nor marks of a public servant, shall be liable to a punishment of\nimprisonment for a term from one year to two years and with a fine from\nfi\u0000y thousand to one hundred thousand rupees, depending on the degree \nof the o\u0000ence committed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Punishment for Giving False Particulars: (1) Whoever, with the", "content": "intention of securing a position of a public servant, or of being continue \nin such a position, or of securing any position or of getting any benefit or \nfacility, gives false particulars regarding his educational qualifications, \nname, names of the father and grandfather, age, caste, surname, address, \nnationality or qualification, or gives false description in any other matters, \nor submits false certificate relating thereto, shall be liable to a punishment \nof imprisonment for a term from six months to one year and of a fine from \nten thousand to twenty thousand rupees, depending on the degree of the \no\u0000ense committed. \n(2) Whoever, being a public servant under the duty of giving \nstatement of his/her property under this Act or any other prevailing \nlaws, gives false statement either having increased or having concealed \nthe actual property belonging to or registered in his/her name or under \nhis/her share entitlement or belonging to his/her joint family, shall be liable \nto a punishment of imprisonment for a term from one month to three \nmonths and the fine not exceeding ten thousand rupees. The property, \nwhich has been concealed in such a manner, shall also be confiscated.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Punishment for Damaging Public Property: Whoever, being a public", "content": "servant, misappropriates, causes loss to or abuses or causes others to do \nso, or destroys or uses for personal purposes, while performing his/her \nduties pertaining to his/her o\u0000ice, shall be liable to be punished pursuant \nto Section 3 and the property which has been misappropriated, damaged, \nmisused or destroyed or caused others to do so, shall be recovered from him/her.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Punishment for Exerting Illegal Pressures: Whoever, either a public", "content": "servant or any other person, compels any public servant or any other \nperson to commit any o\u0000ence punishable urder this Act by exercise of \nfear or threat of under, kidnapping, taking away of property, of causing \nadverse impact on prestige or by exerting any other type of illegal pressure,\nshall be liable to a punishment of imprisonment for a term from four to \neight years and a fine from one hundred thousand to five hundred thousand \nrupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Punishment for Giving False Report: (1) Whoever, either a public", "content": "servant or any other person authorized to carry out auditing in a \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 10/25\ngovernment body or in a public institution, prepares auditing report \nwith mala fide intention having shown the facts not done or happened \nin the transaction or having concealed the facts done or happened, shall be \nliable to a punishment of imprisonment for a term from three months to \none year and to a fine from ten thousand rupees to fi\u0000y thousand rupees \ndepending on the degree of the o\u0000ence committed. \n(2) Save as provided in Sub-section (1), in case any public \nservant or any other person under the duty of submitting report having \nconducted a study or investigation on any subject in connection with\nfunctions of government body or public institution, prepares report with \nmala fide intention having shown the facts actually not done or \nhappened or having concealed the facts actually done or happened, such \npersons shall be liable to a punishment of imprisonment for a term from \nthree months to one year and to the fine from ten thousand rupees to \nfi\u0000y thousand rupees depending on the degree of the o\u0000ence \ncommitted.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Property Deemed to be Acquired Illegally: (1) In case the statement of", "content": "property submitted in accordance with prevailing laws by a public servant \ndeemed to have held a public o\u0000ice in accordance with prevailing laws \nseems to be incompatible or unnatural or in case he/she maintains an \nincompatible or unsuitable lifestyle or it is proved that he/she has given \nsomeone a donation, gi\u0000, grant, present or has lent money beyond \nhis/her capacity, he/she shall prove the sources from which he/she has \nacquired such property and if he fails to do so, such property shall be \ndeemed to have been acquired in an illegal manner. \n(2) In case it has been proved that a public servant has acquired property \nin an illegal manner as referred to in Sub-section (1), he/she shall be liable to a \npunishment of imprisonment for a term not exceeding two years as per the \namount of the property acquired in such a manner, and a fine according to the \namount of property and the illegal property acquired in such a manner shall also \nbe confiscated.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Punishment for Committing Attempts: Except otherwise provided for in", "content": "this chapter, whoever attempts to commit an o\u0000ense punishable under this Act \nshall be liable to half of the punishment to be imposed on the public servant or \nany other person committing such o\u0000ences.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Punishment to Accomplices: Except otherwise provided elsewhere in this", "content": "Act, the accomplices to any o\u0000ense punishable under this Act shall be liable to \nhalf of the punishment to be imposed on the public servant or any other person \ncommitting such o\u0000ences. \nProvided that, the accomplice who has given cash or kind or made \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 11/25\navailable any other type of benefit to the public servant or any other person \ncommitting an o\u0000ence or who has taken such benefit shall be liable to the \npunishment as equal to the person committing the o\u0000ence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Principal to be Deemed to have Committed the O\u0000ence in case a", "content": "Corporate Body Commits O\u0000ence: In case any firm, company or corporate \nbody commits any act that is deemed to be an o\u0000ence under this chapter, the \npartners at the time of commission of the act in case of a firm and the person \nacting as the principal o\u0000icial in case of a company or a corporate body shall be \ndeemed to have committed the o\u0000ence. \nProvided that, in case it is proved that such act has been committed prior to \nthe appointment of the person acting as the principal o\u0000icial, the person who has \ncommitted the act shall be deemed to have committed the o\u0000ence. \nExplanation: For the purpose of this Section, the “the person acting as the \nprincipal o\u0000icial” means the Chairman, Board Member, General Manager, \nManaging Director or the O\u0000icial of a company or corporate body working in \nthe same capacity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Additional Punishment: In case the o\u0000ences under this chapter have been", "content": "committed by an o\u0000ice bearer of a constitutional organ or body to be nominated or \nappointed by o\u0000icer belonging to the special class of Government of Nepal or \no\u0000icers of equivalent rank; Head, General Manager or o\u0000icer of a public \ninstitution of equivalent rank, such person shall be liable to the punishment of \nimprisonment for a term of three years in addition to the punishment prescribed for \nsuch o\u0000ence\nChapter – 3 Investigations, Inquiries and Filling of Cases of\nCorruption\nChapter – 3 Investigations, Inquiries and Filling of Cases of Corruption", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Investigations and Inquiries:", "content": "(1) In case the investigating authority comes to know, through any information, source or a\ncomplaint lodged by any person, that any person has committed or is going to commit\ncorruption, it shall initiate necessary investigations, inquiries and other actions in this regard. \n(2) Notwithstanding anything contained in Sub-Section (1), in case the investigating authority\nhas received information from any source that any person has committed or is going to\nNovember 15, 2018 in The Prevention of Corruption Act, 2059 (2002 A.D)\n134 Comments\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 12/25\ncommit corruption, such authority \nmay take immediate actions including raid, seizure of documents or goods and materials or\narrest of person.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Preliminary Inquiry: The investigating authority shall, upon having received a complaint", "content": "or information that one has committed or is going to commit an o\u0000ence under this Act,\ninitiate preliminary inquiry confidentially as may be \nnecessary.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Seeking Explanation: While conducting preliminary inquiry pursuant to Section 26, in case", "content": "the investigating authority is of the view that the information received is based on facts, it\nmay, having provided particulars \nrelating thereto, seek for comment or explanation from the concerned body or person as may\nbe necessary.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Powers of Investigating Authority: (1) The investigating authority may, while conducting", "content": "investigations and inquiries into o\u0000enses of corruption under this Chapter, exercise the\nfollowing powers: – \n(a) To order a government body, public institution, public servant or any other person to send\nor submit within a certain time any relevant document, documentary evidences or any\nother things before it; \n(b) To conduct inquiry with, or to record the statement of, the public servant or any other\nperson accused of corruption or the person to whom the investigating authority deems\nto having information on the relevant facts; \n(c) The investigating authority may, upon having taken explanation from or upon completing\ninquiry or recording \nthe statement of a public servant or any other person accused of corruption, release such\nperson having executed a bond from him/her to appear as and when required, or\nhaving required him/her to appear on the prescribed date or, in case there is a reasonable\ncause to believe that such public servant or person may abscond or there has been a loss\nof an amount, the investigating authority may ask from him/her to submit a deposit or\nguarantee and require \nhim/her to appear in the prescribed date or in case no deposit or guarantee is produced, keep\nhim/her in custody. \n(2) In case the investigating authority has sent a letter having fixed a time limit to the\nconcerned body, public servant or other person requiring to submit any document or any\nother material or to provide information on any matter or requiring a public servant or any\nother person to appear before it, it shall be done accordingly and in case not done, \nit shall be as follows:- \n(a) In case the concerned government body or public institution does not submit such\ndocument or material or does not provide information within the time prescribed,\nthe investigating authority may send a letter to the concerned \ngovernment body or a public institution to take departmental action against the chief o\u0000icer\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 13/25\nof the concerned government body or a public institution and in case such a letter\nis received, the concerned government body or a public institution shall take actions\nimmediately. \n(b) In case the concerned public servant or any other person does not submit the document\nor material or does not provide information or does not appear within the prescribed period,\nthe investigating authority may impose a fine not exceeding one thousand rupees on such\nperson. \n(c) In case any government body, public institution, public servant or any other person does\nnot do as required to do in writing by the investigating authority even a\u0000er the departmental\naction or imposition of a fine pursuant to Clauses \n(a) or (b), the investigating authority may issue arrest warrant to get the chief o\u0000icer of such\nbody or institute or \nsuch public servant or other person appeared and get such document or material produced\nor acquired necessary \ninformation from him/her. In case the chief o\u0000icer of a body or institution, public servant or\nany other person so arrested does not submit such document or material or does not\ngive information relating thereto, the investigating authority may order for keeping him/her\nin custody for a period of up to \nseven days. \n(3) A\u0000er the investigating authority’s order for departmental \naction or payment of the fine pursuant to Sub-section (2), in case the chief \no\u0000icer of the concerned body or the concerned public servant or any other \nperson submits an application along with reasonable causes for being \nunable to do as required, and if the causes are satisfactory, such order or \norder of fine may be cancelled. \n(4) The investigating authority may conduct or cause to \nconduct a search at any place and seize any necessary materials or \ndocument or Photostat copy thereof while conducting the search. A \nreceipt of the material or document so seized shall be given to the \nconcerned person.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Appointment or Designation of Investigation O\u0000icer: The investigation", "content": "authority may, in order to conduct investigation and inquiries into the \no\u0000ences punishable under this Act, appoint or designate any o\u0000icer under\nit or any government o\u0000icer or any o\u0000icer of a public institution as the \ninvestigation o\u0000icer. \nProvided that, while appointing or designating any government \no\u0000icer, or o\u0000icer of a public institution as the investigating o\u0000icer, \nconsultation shall be held with Government of Nepal or with the Chief \nO\u0000icer of the concerned body, depending on circumstances.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Functions, Duties and Powers of the Investigation O\u0000icer: (1) Functions,", "content": "5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 14/25\nduties and powers of the investigation o\u0000icer shall be as follows:- \n(a) To arrest the o\u0000ender immediately and to take necessary actions; \n(b) To conduct or cause to conduct search at any o\u0000ice, house, \nbuilding, godown, vehicle or any other places while \nconducting investigation and inquiries or while collecting \nevidence into o\u0000ences punishable under this Act; \n(c) To exercise other powers conferred on the investigation o\u0000icer. \n(2) While conducting investigation and inquiries into o\u0000ences \npunishable under this Act, the investigation o\u0000icer shall have all such \npowers, duties, facilities and obligation as the police is having under the \nprevailing laws in respect to recording statements of the accused persons, \nand preparing reports of public inquiries. \n(3) While carrying out functions under Sub-section (2), the \ninvestigation o\u0000icer may exercise the powers equivalent to the powers of a \ncourt to require the accused to appear on prescribed date or to release \nhim/her on deposit or on guarantee or detain him/her in case he is unable \nto furnish such deposit or guarantee as may be necessary.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Keeping Accused in Custody: (1) The investigation o\u0000icer may, in case", "content": "there is su\u0000icient ground that any person having been taken action for an \no\u0000ence under this Act may lose or destroy any evidence or cause \nhindrance in the process of investigation or inquiries or cause adverse \nimpact thereon, keep him/her in custody having given him an order of \ndetention in accordance with the prevailing laws. \n(2) In case the investigation or inquiries with regard to a person is \nnot completed within twenty four hours and it appears that the \ninvestigation needs to be continued having him/her detained, the \ninvestigation o\u0000icer shall detain him/her a\u0000er having him/her presented \nbefore the authority hearing the case and only a\u0000er getting approval \ntherefor from the authority hearing the case. While seeking for approval \nwith the authority hearing the case, the charges against the person \ndetained, its bases, the reason for continuing investigation having him/her \ndetained and if his/her statement has been recorded, the contents of such \nstatement shall be clearly stated. \n(3) The person who has been presented before the authority \nhearing the case for approval of detention pursuant to Sub-section (2) \nmay submit an application while being presented there requesting for his/her \nphysical checkup. \n(4) In case a permission for detention is sought pursuant to Sub- \nsection (2), the authority hearing the case may, having considered whether \nor not the investigation has been carried out in a satisfactory manner and \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 15/25\nif it is found that the investigation is being carried out satisfactorily, give \napproval for detention for a maximum period of six months not \nexceeding thirty days at a time or time and again. \n(5) While seeking for a permission for extension of time duration \nof detention pursuant to Sub-section (4), the person under the custody \nmay, if he/she so wants, submit an application to the authority hearing the \ncase mentioning the reason or basis for his/her not being in detention any \nlonger.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Cooperation of Other Bodies May be Required: (1) The investigating", "content": "authority may, in course of investigations and inquiries into o\u0000enses \npunishable under this Act, ask any government body or public institution \nor any person for cooperation as may be necessary and it shall be the duty of \nsuch body, institution or person to cooperate as and when required. \n(2) The investigating authority may, in course of conducting \ninvestigation and inquiries into o\u0000enses of corruption under this Act, \ntake the help of police force as well. While engaging police personnel in \nthe work, the order issued by the investigating authority shall, with regard \nto the police, be equivalent to the order of the concerned Inspector General \nof Police. \n(3) The investigation o\u0000icer may ask the police o\u0000icer or \npolice personnel subordinate to him/her for help. It shall be the duty of the \nconcerned police o\u0000icer or personnel to assist him/her in case the investigation \no\u0000icer requires such assistance. \n(4) In case the investigating authority deems it fit that because of \nthe very nature of the o\u0000ence under investigation and inquiry, it is \nnecessary to consult an expert engaged in any agency to be involved in such \ninvestigation and inquiry; the investigating authority may ask the \nconcerned body to make such expert available on a temporary \nassignment for a specific period of time, and in case such a demand is \nmade, such body shall, notwithstanding anything contained in the prevailing\nlaws, make available the concerned expert.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Automatic Suspension: In case any public servant is detained pursuant to", "content": "Clause (c) of Subsection (1) of Section 28, Sub-section (3) of Section 30 \nand Section 31, he shall ipso facto be suspended until the period of \ndetention and if a case is filed against him/her pursuant to Section 36, \nhe/she shall ipso facto be suspended unless and until the proceedings of the case is \nover.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Accepting Services: (1) The investigating authority may, while", "content": "conducting investigation, inquiries and taking any other actions \nrelating thereto, require services of experts of the concerned subject or of \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 16/25\nspecialized agencies. \n(2) The investigating authority shall, in order to get the services \nreferred to in sub-section (1), appoint the concerned expert or specialized \nagency and while appointing as such, the investigating authority shall \nhave to enter into an agreement having stated the functions to be carried \nout by such expert or specialized agency, the powers that may be \nexercised, the terms and conditions to be fulfilled, the procedures and \nremuneration and other benefits which such expert or specialized agency is \nentitled to. \n(3) In case the investigating authority is in need of the service of \nemployees of Government of Nepal or of a specialized agency, \nnotwithstanding anything contained in the prevailing laws, such \nemployees shall be deputed for a period required by the investigating \nauthority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Keeping in Postponement: While inquiring and investing under this Act,", "content": "in case it appears that the alleged o\u0000ense could not be proved on the \nbasis of the collected evidence, the investigating authority may keep the \ncomplaint in postponement issuing an order slip along with reasons \nthereof and in case of decision of postponement, the information thereof \nshall be given to the accused person and the complainant. \nProvided that, nothing in this section shall be deemed to have \nprevented to investigate and re-inquire on such complaint if any new evidence \nis found later on.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Filing of cases: In connection with an accusation of commission of", "content": "corruption, in case there is a reasonable cause to believe that the accused has \ncommitted the said o\u0000ence, the investigating authority shall file a case \nbefore the authority having powers to hear the case under the prevailing \nlaws.\nChapter – 4 Provisions Relating to Prevention of\nCorruption\nChapter – 4 Provisions Relating to Prevention of Corruption", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "National Vigilance Center:", "content": "November 15, 2018 in The Prevention of Corruption Act, 2059 (2002 A.D)\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 17/25\n(1) Government of Nepal may establish a National Vigilance Center under the direct control\nand supervision of the \nPrime Minister in order to e\u0000ectively control corruption-oriented acts and to promote\npeople’s awareness against corruption. \n(2) Government of Nepal may designate a special class o\u0000icer of the civil service as the chief\nof the Center referred to in Sub-section (1), and there shall be other o\u0000icials of the services of\nGovernment of Nepal in the \ncenter as may be necessary.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Functions, Duties and Powers of the National Vigilance Center: The  National Vigilance", "content": "Center established under Sub-Section (1) of Section 37 shall have following functions, duties\nand powers:- \n(a) To collect information on whether or not the functions to be carried out by the Ministries,\nDepartments, o\u0000ices of Government of Nepal and public institution are being regularly\ncarried out; \n(b) To alert Ministries, Departments, O\u0000ices of Government of Nepal, or public institution in\ncase the functions to be carried out by them are not found to have been carried out; \n(c) To monitor the statement of property and income given by persons holding a public post\nas per the prevailing laws; \n(d) To make necessary provision for regular surveillance, surprise check and investigation in\ncorruption prone places or works; \n(e) To make necessary recommendations to Government of Nepal with \nregard to the policies, strategies and reformation on laws to be adopted for \ncorruption control; \n(f) To make provision of a complaint box in the Ministries of Government of \nNepal, Departments, O\u0000ices or public institution; \n(g) To provide any suggestion or direction to the concerned bodies with \n(h) To collect necessary description or information concerning \ncorruption from the body or authority working for investigation into \no\u0000ences of corruption and to maintain them updated; \n(i) To forward any information concerning corruption received to it to \nthe concerned bodies; \n(j) To carry out or cause to carry out other incidental functions with \nregard to corruption control; \n(k) To carry out or cause to carry out other functions prescribed by the \nGovernment of Nepal\nNovember 15, 2018 in The Prevention of Corruption Act, 2059 (2002 A.D)\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 18/25\nChapter – 5 Miscellaneous\nChapter – 5 Miscellaneous", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Statement May be Taken or Transaction or Account May be Freeze:", "content": "(1) Notwithstanding anything contained in the existing law, if it appears from any source\nduring the course of investigation into o\u0000ences of corruption that there has been financial\ntransaction or operation of an account in the name of any person with any bank or financial\ninstitution within the country or in any foreign country, the investigating authority may order\nto freeze such transaction or account. The concerned bank or financial institute shall freeze\nsuch transaction or account in accordance with the order of the investigating authority. \nProvided that in case such transaction or account to be freeze is with a bank or financial\ninstitution in a foreign country, the investigation authority may cause to freeze the operation\nof transaction or account through the diplomatic channel. \n(2) The investigating authority may impose a fine of fi\u0000y thousand rupees in maximum to the\nchief of the concerned bank or financial institution located in Nepal not freezing transactions\nor accounts pursuant to Sub-section (1). \n(3) The investigation authority may, if it deems fit in the course of investigation, according to\nthe need, ask for the statement of property belonging to persons holding an o\u0000ice of public\nresponsibility or freeze such \nproperty.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Banning to Issue or Freezing Passport: Notwithstanding anything contained in the", "content": "prevailing laws, the investigating authority may, on the basis of the gravity of the o\u0000ence, the\ncondition, circumstances in which the accused committed the o\u0000ence, degree of the o\u0000ence\nand the pnishment in case of conviction of the o\u0000ence, issue an order to the concerned\nbodies for not issuing passport to any accused or for withholding it if it has been already \nissued.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Restriction to Leave Places: In case an action has been taken against any person under", "content": "this Act, the investigating authority may, on the basis of the gravity of the o\u0000ence, the\ncondition and circumstances in which the accused \ncommitted the o\u0000ence, the degree of the o\u0000ence and the punishment in case of conviction of\nthe o\u0000ence, issue an order to any accused not to leave any place or not to go any particular\nplace without the approval of the investigating \nauthority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Provision Relating to Service of Summons: (1) Notwithstanding anything contained in the", "content": "existing law, while servicing summon in the name of a foreigner in any o\u0000ence under this Act,\nthe summon may be served to the \no\u0000ice or representative of such person within of Nepal, if any, and service of summon in that\nmanner shall be deemed to have duly made. \n(2) In case there is no o\u0000ice or representative referred to in sub-Section \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 19/25\n(1), the summon shall be served to the main place of transaction, or to the address of such\nperson where he resides permanently, or to the address of correspondence given by such\nperson in connection with his business transaction through the means of telex, fax or any\nother means of telecommunication in written form or through registered post, and the\nsummons served in any of such manners shall be deemed to have been duly made. \n(3) Notwithstanding anything contained in Sub-sections (1) or (2), this Section shall not be\ndeemed to have hindered the service of summons according to the provisions of a treaty in\ncase there is a separate provision for \nservice of summons in the name of persons living in a foreign country in any treaty to which\nGovernment of Nepal or of Nepal is a party.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Publication of Notice: Notwithstanding anything contained in the prevailing laws, in case", "content": "it has been reported that no notice could be served while sending a notice or servicing a\nsummon in the name of any person in accordance with this Act or other prevailing laws for\nnot finding the address of such person or for any other reasons, a public notice shall be\npublished least for twice in a national level newspaper (in case of a foreigner in a \nEnglish Daily) having given him/her a time limit of 30 days and having given short description\nas to whether the investigation is underway or the case is already filed at the authority\nhearing the case; and in case a notice \nhas been published in such a way, the notice shall be or summon deemed to have been duly\ndelivered or served to such person notwithstanding anything contained in the prevailing\nlaws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Obligations of government bodies and public institutions: The chief of a government body", "content": "and public institution shall, in case any information has been received that corruption has\nbeen committed at his o\u0000ice or any other o\u0000ice under him, immediately take the\nrelated documents or file under his custody and keep it safe, and upon having \ninquired with the persons and o\u0000icials related to such subject and upon having known the\nreality, if there appears any reason of commission of corruption, he shall forward such\ndocuments to the concerned body for \ninvestigation and inquiry.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Case May be Filed against Retired Person: Nothing in this Act shall be deemed to have", "content": "prevented filling of a case against a retired public servant in connection with commission of\ncorruption having embezzled \nor causing loss to government or public property or the property belonging to an\norganization owned by Government of Nepal even a\u0000er such public servant is retired from\nthe service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "No Hindrance to Initiate Proceedings and Finalize Case:", "content": "Notwithstanding anything contained in the prevailing laws, there shall be no hindrance to\ninitiate proceedings and finalize a case even if the accused or defendant dies before or a\u0000er a\ncase under this Act is filed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Confiscation of Property: In case it is proved that any person has earned property having", "content": "5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 20/25\ncommitted any act which is deemed to have committed corruption under this Act or other\nprevailing laws and has \nkept such property and the property accrued therefrom in his/her own name or in the name\nof anybody else such property shall be confiscated. \nProvided that, in case the ownership of such property is transferred to any person and in case\nthe price of such a property is quoted, the transaction involving such amount shall be treated\nas a simple loan deed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Order to Freeze Property of a Foreigner: (1) In case any foreigner who does not appear", "content": "before the investigating authority in pursuance of a notice sent by the investigating authority\nor summon served pursuant to \nSection 42 is having any property, entitlement, interest or concern within of Nepal, the\ninvestigating authority may order to maintain a status quo with regard to them or not to\nallow to take such property, \nentitlement, interest or concern outside of Nepal unless and until such a person appears\nbefore the investigating authority, and it shall be the duty of all concerned to abide by such\nan order. \n(2) The investigating authority may impose a fine of one thousand rupees in maximum to the\nperson who does not abide by the order made pursuant to Sub- section (1) and in case any\ntype of loss or damage is caused to Government of Nepal or a public institution because  of\nnon-observance of such an order, such loss shall also be recoved from \nhim/her.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Punishment for Filing False Complaint: In case it is found that any person has filed a false", "content": "complaint against any public servant or person without having any reasonable ground for\nfiling a complaint and with the \nintention of causing any type of loss, damage or harassment, the investigating authority may\nimpose a fine not exceeding five thousand rupees on him.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Provision Relating to Statement of Property: (1) Whoever joins a public o\u0000ice shall, within", "content": "sixty days from the date of joining the public o\u0000ice, and whoever is engaged in a public o\u0000ice\non the date of commencement of this Section shall, within sixty days from the date of\ncommencement of this Act, and therea\u0000er within sixty days from the \ndate of completion of each fiscal year, submit the up dated statement of property in his/her\nname or in the name of his/her family members along with the sources or evidence thereof to\nthe body or authority \nprescribed by Government of Nepal having published a notification in the Nepal Gazette. \n(2) In case the person assuming a public o\u0000ice who is unable to submit the statement of\nproperty within the time limit referred to in Sub- section (1) makes a request for extension of\nthe time limit having stated \ntherein the reasons for his/her not being able to submit such statement, the concerned body\nor authority may extend the time limit for a period of thirty days in maximum. \n(3) The person assuming a public o\u0000ice who does not submit the statement of property\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 21/25\nwithin the time limit extended pursuant to Sub- section (2) shall be liable to a fine of five\nthousand rupees and the \nconcerned body or o\u0000icial may investigate having suspected that there is illegal property in\nhis/her and his/her family member’s names. \n(4) The statement of property submitted under this section Shall be confidential. \nProvided that, if statement of property is required in connection with investigation and\ninquiries under this Act, such statement may be made available to the concerned authority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Punishment to Persons Causing Hindrance and Obstruction: The authority hearing the", "content": "case may, on the basis of the report of investigating authority, impose a punishment of\nimprisonment of a term of six months in \nmaximum or a fine up to five thousand rupees in maximum or both to a person who causes\nhindrance or obstruction in actions relating to investigation and inquiries under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "52", "title": "Confidentiality of Information: (1) No notice, information or evidence  received to,", "content": "collected by, the investigating authority in connection with investigation and inquiry in an\no\u0000ence of corruption shall be publicly notified \nbefore filing of case. \n(2) Notwithstanding anything contained in Sub-section (1), the investigating authority may\npublicize particulars of inquiry and investigation of any matter of public importance which it\ndeems fit as may be necessary.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "Departmental Action to Employees Involved in Inquiries and Investigation: In connection", "content": "with implementation of this Act, in case it is proved that the investigation o\u0000icer or other\nemployee engaged in investigation \nand inquiries has committed any act knowingly with the intention of causing harassment to\nany person, departmental action shall be taken against such employees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "To be subjected to Imprisonment: Notwithstanding anything contained in the prevailing", "content": "laws, the person having been punished by a court with a term of imprisonment shall be\nsubjected only to imprisonment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Remission in the Claim of Punishment: The investigating authority may give complete or", "content": "partial remission in the claim of punishment with regard to the accused who assists in the\nprocess of investigation carried out under this \nAct having him/herself presented as a witness on its behalf. \nProvided that in case other evidences do not prove his assistance or in case he becomes\nhostile later on, the case may be filed against him again notwithstanding anything contained\nin this Act or in other prevailing laws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "No Action to be Taken: Notwithstanding anything contained in the prevailing laws, no", "content": "action shall be taken against a public servant for disclosing confidentiality under the law\nrelating to the terms and condition of \nhis/her service who gives information for taking legal action in case of corruption committed\nor going to be committed or for preventing to be committed.\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 22/25", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Delegation of Power: (1) The investigating authority may, by publication of a notification", "content": "in the Nepal Gazette, delegate its all or any power conferred on it by this Act to any of the\nGovernment of Nepal’s gazetted level o\u0000icers. \n(2) While delegating power pursuant to Sub-section (1), the territorial jurisdiction for the\npowers to be accountable by such o\u0000icer shall be as prescribed in such notification. \n(3) The o\u0000icer exercising the power conferred on him under sub- Section (1) shall, for that\npurpose, be responsible to the investigating authority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Provision Relating to Rewards: The investigating authority may give an appropriate", "content": "reward to the person assisting it in connection with inquires, investigation or collection of\nevidences in the o\u0000ences punishable under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "Special Provisions Relating to Cases of Corruption: Notwithstanding anything contained", "content": "in the prevailing laws, it shall be as follows in the following matters with regard to the cases\nfiled under this Act:- \n(a) In case any public servant or any other person has, while committing or in connection\nwith committing an act that is deemed to be an o\u0000ence under other prevailing laws, there\nshall be no hindrance to file separate case in \naccordance with other prevailing laws. \n(b) In case there has been adverse impact caused on the rights, property or interests of any\nperson while committing or in connection with committing an act that is deemed to be an\no\u0000ence under this Act by a public servant or\nany other person, there shall be no hindrance for such person to file a \nseparate case. \n(c) In cases where a case has been filed against a person for an o\u0000ence under this Act and it\nappears later on, a\u0000er having examined the  evidence, that the case must be filed against\nother person as well, there \nshall be no hindrance to file a separate charge sheet against such person. \n(d) Nothing shall be deemed to prevent filling of a separate case against any public servant or\nperson for o\u0000enses to be liable under this Act, even if the separate case has been already filed\nagainst such person in order to \nrecover loss and damages made by such person to Government of Nepal or public institution\nillegally; \n(e) In case, where a case has been filed under this Act against any public servant or other\nperson, there shall be no hindrance to file a case under this Act or the case filed shall not be\ndismissed merely for the reason that \nthere is a legal provision of recovery of the loss caused to Government of Nepal or a public\ninstitution from such public servant or other person. (f) No cases filed under this Act shall be\nwithdrawn or compromised.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "Informer and his/her details to be kept confidential: The name or address of an informer", "content": "providing information that an o\u0000ence under this Act has been committed or going to be\ncommitted shall be kept confidential in case \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 23/25\nhe/she so requests.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Unclaimed goods to be entitled to Government of Nepal: (1) In case no owner of the", "content": "goods related to the o\u0000ence punishable under this Act is traced, the investigating authority\nshall publish a public notice requiring the claimant, if \nany, of the goods so seized to claim the goods, within a time limit of thirty five days. \n(2) In case, no claim is made within the time limit referred to in sub- section (1) or even if the\nclaim is made but in absence of proof the claim is not tenable, such goods shall be the\nproperty of Government of Nepal having treated \nsuch goods as unclaimed goods.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Goods may be sold: (1) In case it appears that any goods seized in connection with an", "content": "o\u0000ence punishable under this Act would be damaged or broken for storing for a long time\ndue to rust or for any other reason or would be rotten or damaged or price of such goods\nwould go down for being old or would be useless or it could not be stored or maintained for\nlack of space, such goods may be sold having completed the process thereof in accordance\nwith the \nprevailing laws. \n(2) The amount received from the sale pursuant to Sub-section\n(1) shall be deposited to the deposit accounts. In case it has been decided that  such goods\nhas to be given to the concerned owner, he shall be entitled only to the amount received from\nthe sale.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "No Hindrance to Exercise Powers: Nothing in this Act shall be deemed to have hindered", "content": "any authority or o\u0000icer to exercise powers under other prevailing laws with regard to\ninvestigation, inquires, other actions and filing \nor cases relating to corruption.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Power to Frame Rules: Government of Nepal may frame necessary Rules for implementing", "content": "the objectives of this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Amendment, Repeal and Saving:", "content": "(1) The following Sections of the Revenue (Investigation and Control) Act, 2052 have been\nrepealed,- \n(a) Clause (c) of Section 2; \n(b) Sub-section (2) of Section 6; \n(c) The terms “or employee” appearing in sub-Section (4) of Section 9; \n(d) Sub-section (2) of Section 18; \n(e) Sub-section (2) of Section 21; \n(f) Sub-section (2) of Section 23; \n(g) The terms “or corruption” frequently used in place to place; \n(h) Section 5, chapter 4 and Section 25. \n(2) The Prevention of Corruption Act, 2017 has been repealed. \n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 24/25\nContact \n Address  : International Convention Centre, \nNew Baneshwor, Kathmandu \n Phone  : (+977)4481197, (+977)4481043, (+977)4481046, (+977)4481059 \n Email : info@lawcommission.gov.np  \n Fax  : 4481704  \nO\u0000ice of the Prime Minister and Council of Ministers \nSupeme Court of Nepal \nWEB LINKS\n(3) All actions taken and proceedings initiated under the Prevention of Corruption Act, 2017\nshall be deemed to have been taken or initiated under this Act.\nNovember 15, 2018 in The Prevention of Corruption Act, 2059 (2002 A.D)\nNepal Law Commission is a statutory independent body created by the Nepal Law Commission\nAct, 2007 to keep the law under review and to recommend reform where it is needed.\nWELCOME\nHOME\nABOUT US\nRECOMMENDATIONS\nRIGHT TO INFORMATION\nPUBLICATIONS\nANNUAL REPORT\nOTHERS\n5/18/2021 The Prevention of Corruption Act, 2059 (2002 A.D) – Nepal Law Commission\nhttps://www.lawcommission.gov.np/en/archives/category/documents/prevailing-law/statutes-acts/the-prevention-of-corruption-act-2059-2002-a-d 25/25\nFederal Parliament  \nMinistry of Law, Justice and Parliamentary A\u0000airs \nAttorney General  \nDepartment of Printing \nO\u0000icial Portal of the Government of Nepal \nProvince 1 \nProvince 2 \nBagmati Province \nGandaki Province \nLumbini Province \nKarnali Province \nSudurpaschim Province \n \n  \nMobile Apps \n \nSOCIAL MEDIA\n© 2021 Nepal Law Commission \nDeveloped by Meronetwork", "children": []}]}]$CODExfdad488d5fbd$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
